prelude_js:
// 本片数字由 scratchpad/v16.py 独立核算：
//   AB 例子（S&B 经典 8 回合，γ=1）：V(B)=6/8=0.7500 两法一致；
//     V(A) 批 MC = 0.0000（最小化对观测回报的 MSE，扫格自证），批 TD = 0.7500（确定性等价 MDP）
//   expectimax 叶子数 (|S||A|)^H：|S|=|A|=361、H=3 已是 2.21e15；
//     口述的「S times A to the H」有歧义 —— (|S||A|)^H 与 |S|·|A|^H 在 (10,4,5) 上差 1e4 倍
//   规划时该采谁（A1 均值高且已测准 n=400，A2 均值低且很不确定 n=9，再花 400 个样本）：
//     花在 A1 -> 两区间分离的比例 0.0604；花在 A2 -> 0.5274。<b>采不确定的那个好 8.7 倍</b>
function leaves(S,A,H){return Math.pow(S*A,H);}
function ciHalf(n,sd){return 1.96*(sd||1)/Math.sqrt(n);}

/* ══ L16 片内图：整部片共用同一棵搜索树（对照 lecture16_postclass.pdf p.40-44）══
   坐标写死并复用，是为了让九个知识点看到的是「同一棵树在长」，
   而不是九张互不相干的示意图。 */
var RX=640, RY=104;                                  /* 根：当前真实状态 s_t */
var LV1=[[372,182],[640,182],[908,182]];             /* 第一层：三个候选动作 */
var LV2=[[286,262],[468,262],[744,262],[992,262]];   /* 第二层 */
var DIVY=292;                                        /* 树策略 / 默认策略 的分界 */
var TERMY=372;

function mE(x1,y1,x2,y2,cls){                        /* 树边 */
  return E.gS.append("path").attr("class","tedge "+(cls||""))
    .attr("d","M"+x1+","+y1+"L"+x2+","+y2);
}
function mN(x,y,r,cls){                              /* 状态节点 */
  return E.gS.append("circle").attr("class","tnode "+(cls||""))
    .attr("cx",x).attr("cy",y).attr("r",r||17);
}
function mT(x,y,cls){                                /* 终止方块（课件里的 T） */
  return E.gS.append("rect").attr("class","tnode "+(cls||""))
    .attr("x",x-11).attr("y",y-11).attr("width",22).attr("height",22).attr("rx",3);
}
/* 节点下方的访问计数 / 均值，UCT 全靠它 */
function mStat(x,y,n,q,cls){
  if(n!=null) note("N="+n,x,y+30,cls||"sm");
  if(q!=null) note("Q="+q,x,y+46,cls||"sm");
}
/* 课件 p.40-44 那条红线：上面是树策略，下面是默认策略 */
function mDiv(){
  E.gS.append("path").attr("class","axline r")
    .attr("d","M210,"+DIVY+"L1070,"+DIVY);
  note("树策略",232,DIVY-10,"r");
  note("默认策略 rollout",268,DIVY+20,"r");
}
/* 分界线以下的 rollout：一串交替的点，落到终止方块并给出结局 */
function mRoll(x,out,cls){
  var ys=[DIVY+16,DIVY+42,DIVY+68], px=x;
  for(var i=0;i<ys.length;i++){
    var nx=x+(i%2?14:-14);
    mE(px,i?ys[i-1]:DIVY,nx,ys[i],cls);
    mN(nx,ys[i],7,cls); px=nx;
  }
  mE(px,ys[2],x,TERMY,cls);
  mT(x,TERMY,cls);
  note(String(out),x,TERMY+5,"ink");
}

